  ('b5100dc7-aaec-52fd-82dd-7a3d39e8770a', 'acade111-0000-4000-8000-000000000001', 'HRD-007', 'CHK_COMMENCEMENT_WINDOW', 'CHK_COMMENCEMENT_WINDOW', 'SBL_KHAS', 'SBL_KHAS', 'ANY', 'GRANT', 'BINDING', 'Commencement window', 'FAIL', 'training_start', 'LTE', 'FIELD', 'grant_approval', 90, 'DAY', '{}'::jsonb, '2026-06-15', NULL, '2026-06-20T00:00:00+08:00', NULL, 'ACTIVE', NULL, NULL, NULL, 'DOC-0188', 'Circular 2/2026', '3.4', 5, 'Training shall commence within ninety (90) days of the date of grant approval, failing which the grant lapses.', ARRAY['CHK_COMMENCEMENT_WINDOW']::text[], 'acade111-0001-4000-8000-000000000005', '2026-06-20T00:00:00+08:00', '2026-06-20T00:00:00+08:00', 'AGENT', 'agent_knowledge', 'Knowledge agent'),
  ('5f5bf1b6-5c8b-544d-9555-572073db767c', 'acade111-0000-4000-8000-000000000001', 'HRD-009', 'CHK_CLAIM_WINDOW', 'CHK_CLAIM_WINDOW', 'SBL_KHAS', 'SBL_KHAS', 'ANY', 'CLAIM', 'BINDING', 'Claim submission window', 'FAIL', 'claim_submitted', 'LTE', 'FIELD', 'training_completion', 183, 'DAY', '{}'::jsonb, '2024-01-01', NULL, '2026-06-20T00:00:00+08:00', NULL, 'ACTIVE', NULL, NULL, NULL, 'DOC-0188', 'Circular 2/2026', '5.2', 9, 'Claims shall be submitted within six (6) months from the date of completion of the training programme.', ARRAY['CHK_CLAIM_WINDOW']::text[], 'acade111-0001-4000-8000-000000000005', '2026-06-20T00:00:00+08:00', '2026-06-20T00:00:00+08:00', 'AGENT', 'agent_knowledge', 'Knowledge agent'),
