  ('1029f832-4895-55cb-bb95-f76d32d0ffae', 'acade111-0000-4000-8000-000000000001', 'HRD-014', 'CHK_LEAD_TIME', 'CHK_LEAD_TIME', 'SBL_KHAS', 'SBL_KHAS', 'ANY', 'GRANT', 'BINDING', 'In-house application lead time', 'FAIL', 'training_start', 'GTE', 'FIELD', 'grant_approval', 14, 'DAY', '{}'::jsonb, '2026-06-15', NULL, '2026-06-20T00:00:00+08:00', NULL, 'ACTIVE', '2262fbb9-36c6-5b0c-85ea-7f95ef42775c', NULL, NULL, 'DOC-0188', 'Circular 04/2026', '3.2', 4, 'Employers are required to submit grant applications at least fourteen (14) days before the commencement date of in-house training programmes.', ARRAY['CHK_LEAD_TIME']::text[], 'acade111-0001-4000-8000-000000000005', '2026-06-20T00:00:00+08:00', '2026-06-20T00:00:00+08:00', 'AGENT', 'agent_knowledge', 'Knowledge agent'),
  ('2b321d28-ab60-5b20-8418-128c4ce0aa48', 'acade111-0000-4000-8000-000000000001', 'HRD-015', 'CHK_LEAD_TIME', 'CHK_LEAD_TIME', 'SBL', 'SBL', 'ANY', 'GRANT', 'BINDING', 'Public programme application lead time', 'FAIL', 'training_start', 'GTE', 'FIELD', 'grant_approval', 3, 'DAY', '{}'::jsonb, '2026-06-15', '2026-12-31', '2026-06-20T00:00:00+08:00', NULL, 'ACTIVE', NULL, 'fc44471b-eac7-5b97-9280-55014d2e33bf', NULL, 'DOC-0188', 'Circular 2/2026', '3.3', 4, 'Applications for public programmes shall be submitted at least three (3) days before the commencement date.', ARRAY['CHK_LEAD_TIME']::text[], 'acade111-0001-4000-8000-000000000005', '2026-06-20T00:00:00+08:00', '2026-06-20T00:00:00+08:00', 'AGENT', 'agent_knowledge', 'Knowledge agent'),
